    const estimatedTimesMap = new Map<number, { estimatedDeparture?: string; estimatedArrival?: string }>();
    for (const t of estimatedTimesRows) {
      const existing = estimatedTimesMap.get(t.flightId) ?? {};
      if (t.timeType === 'EstimatedBlockOff') {
